  if(NOT TARGET ${OP_GRAPH_NAME}_obj)
    if(BUILD_WITH_INSTALLED_DEPENDENCY_CANN_PKG)
      npu_op_library(${OP_GRAPH_NAME}_obj GRAPH)
    else()

